"use client";

import React, { useMemo } from 'react';
import { Canvas, ThreeElements, useThree } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import * as THREE from 'three';

interface LogoMonogramProps extends Omit<ThreeElements['mesh'], 'scale'> {
  scale?: number | [number, number, number];
  position?: [number, number, number];
  radius?: number;
  holeRadius?: number;
  color?: string;
  standalone?: boolean;
  responsive?: boolean;
}

const createHexagonVertices = (radius: number, offsetAngle: number = 0): [number, number][] => {
  const vertices: [number, number][] = [];
  for (let i = 0; i < 6; i++) {
    const angle = (i * Math.PI) / 3 + offsetAngle;
    vertices.push([radius * Math.cos(angle), radius * Math.sin(angle)]);
  }
  return vertices;
};

const ResponsiveLogoMesh: React.FC<LogoMonogramProps> = ({ 
  scale = 1, 
  position = [0, 0, 0],
  radius = 1,
  holeRadius = 0.5,
  color = '#ffffff',
  responsive = true,
  ...props 
}) => {
  // Use Three.js viewport for responsive scaling
  const { viewport } = useThree();

  // Calculate responsive scale based on viewport
  const responsiveScale = useMemo(() => {
    if (!responsive) return scale;

    // Base scale calculation - adjust these values to fine-tune responsiveness
    const baseViewportWidth = 10; // Reference viewport width
    const scaleFactor = viewport.width / baseViewportWidth;

    // Apply limits to prevent too small or too large scaling
    const minScale = 0.3;
    const maxScale = 3;
    const clampedScale = Math.max(minScale, Math.min(maxScale, scaleFactor));

    // Apply to existing scale
    if (Array.isArray(scale)) {
      return [scale[0] * clampedScale, scale[1] * clampedScale, scale[2] * clampedScale] as [number, number, number];
    }
    return scale * clampedScale;
  }, [viewport.width, scale, responsive]);

  // Define the 12 ring colors from innermost to outermost
  const ringColors = [
    '#3FE7F9', // outermost
    '#39D6F6',
    '#34C6F4',
    '#2EB5F1',
    '#28A4EE',
    '#2393EB',
    '#1D83E9',
    '#1872E6',
    '#1261E3',
    '#0C50E0',
    '#0740DE',
    '#012FDB' // innermost
  ];

  const geometries = useMemo(() => {
    const geoms: THREE.ShapeGeometry[] = [];

    // Create outer hexagon shell
    const outerShape = new THREE.Shape();
    const outerVertices = createHexagonVertices(radius, Math.PI / 4);
    outerShape.moveTo(outerVertices[0][0], outerVertices[0][1]);
    outerVertices.slice(1).forEach(([x, y]) => outerShape.lineTo(x, y));
    outerShape.closePath();

    // Create the largest inner hole
    const holePath = new THREE.Path();
    const innerVertices = createHexagonVertices(holeRadius, Math.PI / 4);
    holePath.moveTo(innerVertices[0][0], innerVertices[0][1]);
    innerVertices.slice(1).forEach(([x, y]) => holePath.lineTo(x, y));
    holePath.closePath();
    outerShape.holes.push(holePath);

    geoms.push(new THREE.ShapeGeometry(outerShape));

    // Create 12 hexagonal rings inside the hole
    const ringStep = holeRadius / 12;

    for (let i = 0; i < 12; i++) {
      const outerRingRadius = holeRadius - (i * ringStep);
      const innerRingRadius = holeRadius - ((i + 1) * ringStep);

      // Create ring shape (hexagon with hexagonal hole)
      const ringShape = new THREE.Shape();
      const ringOuterVertices = createHexagonVertices(outerRingRadius, Math.PI / 4);
      ringShape.moveTo(ringOuterVertices[0][0], ringOuterVertices[0][1]);
      ringOuterVertices.slice(1).forEach(([x, y]) => ringShape.lineTo(x, y));
      ringShape.closePath();

      // Add inner hole (except for the innermost ring)
      if (innerRingRadius > 0.01) {
        const ringHolePath = new THREE.Path();
        const ringInnerVertices = createHexagonVertices(innerRingRadius, Math.PI / 4);
        ringHolePath.moveTo(ringInnerVertices[0][0], ringInnerVertices[0][1]);
        ringInnerVertices.slice(1).forEach(([x, y]) => ringHolePath.lineTo(x, y));
        ringHolePath.closePath();
        ringShape.holes.push(ringHolePath);
      }

      geoms.push(new THREE.ShapeGeometry(ringShape));
    }

    return geoms;
  }, [radius, holeRadius]);

  const materials = useMemo(() => 
    [
      // Outer hexagon material
      new THREE.MeshBasicMaterial({
        color: color,
        side: THREE.DoubleSide,
        transparent: true,
        opacity: 1,
      }),
      // Ring materials with specified colors
      ...ringColors.map(ringColor => 
        new THREE.MeshBasicMaterial({
          color: ringColor,
          side: THREE.DoubleSide,
          transparent: true,
          opacity: 1,
        })
      )
    ], [color]
  );

  return (
    <group>
      {/* Outer hexagon */}
      <mesh 
        geometry={geometries[0]} 
        material={materials[0]} 
        scale={responsiveScale} 
        position={position} 
        {...props} 
      />
      {/* 12 hexagonal rings */}
      {geometries.slice(1).map((geometry, index) => (
        <mesh
          key={index}
          geometry={geometry}
          material={materials[index + 1]}
          scale={responsiveScale}
          position={position}
          {...props}
        />
      ))}
    </group>
  );
};

const LogoMonogram: React.FC<LogoMonogramProps> = ({ 
  standalone = false,
  ...props 
}) => {

  if (standalone) {
    return (
      <div style={{ width: '100%', height: '100%' }}>
        <Canvas 
          camera={{ position: [0, 0, 8], fov: 75 }}
          style={{ width: '100%', height: '100%' }}
        >
          <ambientLight intensity={1} />
          <ResponsiveLogoMesh {...props} />
          <OrbitControls />
        </Canvas>
      </div>
    );
  }

  return <ResponsiveLogoMesh {...props} />;
};

export default LogoMonogram;

"use client";

import { useRef } from "react";
import { useFrame, useThree } from "@react-three/fiber";
import { Group, Mesh, Material } from "three";
import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { IcebergObject } from "../objects/IcebergObject";
import { OceanWaves } from "../objects/OceanWaves";
import { DeepSeaView } from "../objects/DeepSeaView";

gsap.registerPlugin(ScrollTrigger, useGSAP);

/**
 * AnimatedIcebergScene - Section2 with iceberg
 */
export default function AnimatedIcebergScene() {
  const groupRef = useRef<Group>(null);
  const icebergRef = useRef<Group>(null);
  const timeRef = useRef(0);

  // Floating animation synchronized with waves
  useFrame((state, delta) => {
    if (!icebergRef.current) return;
    
    timeRef.current += delta * 0.8; // Match wave speed
    
    // Gentle bobbing motion matching wave patterns
    const bob1 = Math.sin(timeRef.current * 1.2) * 0.08;
    const bob2 = Math.sin(timeRef.current * 0.9) * 0.05;
    const bob3 = Math.cos(timeRef.current * 1.5) * 0.03;
    
    // Subtle rocking motion
    const rock1 = Math.sin(timeRef.current * 0.6) * 0.02;
    const rock2 = Math.cos(timeRef.current * 0.8) * 0.015;
    
    // Apply floating motion
    icebergRef.current.position.y = bob1 + bob2 + bob3;
    icebergRef.current.rotation.x = rock1;
    icebergRef.current.rotation.z = rock2;
  });

  useGSAP(() => {
    if (!groupRef.current) return;

    // Set initial state - hidden
    gsap.set(groupRef.current.scale, { x: 0, y: 0, z: 0 });
    gsap.set(groupRef.current.position, { x: 0, y: 0, z: 0 });

    // Scroll-based animation for Section2
    gsap.timeline({
      scrollTrigger: {
        trigger: "#section2",
        start: "top center",
        end: "bottom center",
        scrub: 1,
        markers: true, // Debug markers - remove when done
        onEnter: () => console.log("Section2 entered"),
        onLeave: () => console.log("Section2 left"),
      },
    })
      .to(groupRef.current.scale, {
        x: 1.5,
        y: 1.5,
        z: 1.5,
        duration: 0.5,
        ease: "power2.out",
      })
      .to(groupRef.current.rotation, {
        y: Math.PI * 2,
        duration: 1,
        ease: "linear",
      }, "<")


    gsap.timeline({
      scrollTrigger: {
        trigger: "#section3",
        start: "top center",
        end: "bottom center",
        scrub: 1,
        markers: true, // Debug markers - remove when done
        onEnter: () => console.log("Section3 entered"),
        onLeave: () => console.log("Section3 left"),
      },
    })
      .to(groupRef.current.scale, {
        x: 2,
        y: 2,
        z: 2,
        duration: 0.5,
        ease: "power2.out",
      })
      .to(groupRef.current.position, {
        y: 20,
        duration: 1,
        ease: "linear",
      }, "<")

  }, []);

  return (
    <>
      <group ref={groupRef} position={[0, -5, 0]}>
        {/* Ambient light for overall illumination */}
        <ambientLight intensity={0.6} />
        
        {/* Key light - main iceberg illumination */}
        <directionalLight 
          position={[5, 10, 5]} 
          intensity={2} 
          color="#ffffff"
          castShadow
        />
        
        {/* Fill lights for ice crystalline effect */}
        <pointLight position={[10, 5, 10]} intensity={1.5} color="#60a5fa" />
        <pointLight position={[-10, 5, 10]} intensity={1.5} color="#a855f7" />
        <pointLight position={[0, -5, 8]} intensity={1} color="#3FE7F9" />
        
        {/* Rim light from behind */}
        <spotLight 
          position={[0, 2, -5]} 
          intensity={2.5} 
          color="#ffffff"
          angle={0.6}
          penumbra={0.5}
        />
        
        {/* Iceberg with floating animation */}
        <group ref={icebergRef}>
          <IcebergObject />
        </group>
        
        <OceanWaves 
          radius={15} 
          segments={512} 
          waveHeight={0.15} 
          waveSpeed={0.8} 
        />
        
        {/* Deep sea view below the surface */}
        <DeepSeaView 
          radius={15}
          depth={10}
        />
      </group>
    </>
  );
}
